import { OWLManager } from "owlapi/apibinding";
import { StringDocumentSource } from "owlapi/io";
import { OWLOntologyLoaderConfiguration } from "owlapi/model";

/** Hand-authored independent attachment witness, not generated by the exporter. */
export const METADATA_WITNESS = `Ontology(<urn:witness> <urn:witness:v1>
 Annotation(<urn:creator> <urn:person>)
 Annotation(<http://www.w3.org/2000/01/rdf-schema#label> "é😀"@es)
 Declaration(Class(<urn:C>)) Declaration(Class(<urn:D>)) Declaration(Class(<urn:E>))
 SubClassOf(Annotation(<urn:note> "first") <urn:C> <urn:D>)
 SubClassOf(Annotation(Annotation(<urn:nested> "inner") <urn:note> "second") <urn:C> <urn:E>)
 AnnotationAssertion(<urn:new-field> <urn:C> "01"^^<http://www.w3.org/2001/XMLSchema#integer>)
 AnnotationAssertion(<urn:new-field> <urn:C> "1"^^<http://www.w3.org/2001/XMLSchema#integer>)
 AnnotationAssertion(<urn:new-field> <urn:C> ""^^<urn:new-datatype>)
 AnnotationAssertion(<urn:new-field> <urn:C> "urn:person"^^<http://www.w3.org/2001/XMLSchema#anyURI>)
 AnnotationAssertion(<urn:new-field> <urn:C> <urn:person>)
)`;

export async function loadMetadataWitness(source = METADATA_WITNESS) {
  return OWLManager.createOWLOntologyManager({
    behaviorProfileId: "normative-v1",
  }).loadOntologyFromOntologyDocument(
    new StringDocumentSource(source),
    new OWLOntologyLoaderConfiguration({
      parsingMode: "strict",
      remoteImports: false,
      remoteJsonLdContexts: false,
      loadAnnotationAxioms: true,
    }),
  );
}

export const witnessContext = {
  behaviorProfileId: "normative-v1",
  owlapi:
    "git+https://github.com/Hadden-Industries/owlapi.git#36e28374447d94d9734960aaed6d3ab4be52ca17",
  pairedOwlSha256: "0".repeat(64),
};
